// Image imports converted at build time by vite-imagetools (via @sveltejs/enhanced-img), e.g.
//   import shot from './shot.png?w=1920&format=webp'   →  URL of the generated WebP
// Kept in its own file (no imports/exports) so this stays a global ambient declaration.
declare module '*format=webp' {
	const src: string;
	export default src;
}
